import { inventoryDocumentSchema as validatedInventoryDocument } from "../schemas/warehouseSchemas";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { z } from "zod";
import type { categorySchema, documentLineSchema, inventoryDocumentPatchSchema, inventoryDocumentSchema, itemSchema, postDocumentSchema, reverseDocumentSchema, stockCountSchema, stockCountUpdateSchema, uomSchema, warehouseListQuerySchema, warehouseSchema } from "@/features/warehouse/schemas/warehouseSchemas";
import type { InventoryBalance, InventoryDocument, InventoryDocumentLine, InventoryItem, ItemCategory, StockCount, StockLedgerEntry, UnitOfMeasure, Warehouse, WarehouseDashboard } from "@/features/warehouse/types/warehouseTypes";
import { AppError } from "@/lib/api/errors";
