import { recordAuditLog } from "@/services/audit/auditLog";
import { safeUploadName, validateUploadedFile } from "@/lib/security/filePolicy";
type Row=Record<string,unknown>;
function db(){const client=getSupabaseServiceClient();if(!client)throw new AppError("SERVER_ERROR","Supabase chưa được cấu hình.");return client;}
function text(row:Row,key:string,fallback=""){const value=row[key];return typeof value==="string"?value:fallback;}
function optional(row:Row,key:string){const value=text(row,key);return value||undefined;}
function nested(row:Row,key:string):Row|undefined{const value=row[key];if(Array.isArray(value))return value[0] as Row|undefined;return value&&typeof value==="object"?value as Row:undefined;}
async function actor(client:SupabaseClient,user:AuthenticatedUser){let query=client.from("app_accounts").select("id,employee_id").limit(1);query=/^[0-9a-f-]{36}$/i.test(user.id)?query.eq("id",user.id):query.eq("primary_email",user.email);const{data,error}=await query.maybeSingle();if(error)throw new AppError("SERVER_ERROR","Không thể xác định tài khoản kho.");return{accountId:data?.id?String(data.id):undefined,employeeId:data?.employee_id?String(data.employee_id):undefined};}
async function scopedWarehouseIds(client:SupabaseClient,user:AuthenticatedUser,operate=false){if(can(user.permissions,"warehouse.view_all"))return undefined;const identity=await actor(client,user);if(!identity.accountId)return[];let query=client.from("warehouse_user_scopes").select("warehouse_id").eq("account_id",identity.accountId).eq("can_view",true);if(operate)query=query.eq("can_operate",true);const{data,error}=await query;if(error)throw new AppError("SERVER_ERROR","Không thể xác định phạm vi kho.");return(data??[]).map((row)=>String(row.warehouse_id));}
async function assertWarehouseAccess(client:SupabaseClient,user:AuthenticatedUser,warehouseId:string,operate=false){const scope=await scopedWarehouseIds(client,user,operate);if(scope&&!scope.includes(warehouseId))throw new AppError("PERMISSION_DENIED","Bạn không thuộc phạm vi kho này.");}
function requireWarehousePermission(user:AuthenticatedUser,permission:Permission){if(!can(user.permissions,permission))throw new AppError("PERMISSION_DENIED");}

function mapItem(row:Row):InventoryItem{const category=nested(row,"item_categories"),uom=nested(row,"units_of_measure"),image=nested(row,"primary_image");return{id:text(row,"id"),itemCode:text(row,"item_code"),name:text(row,"name"),shortName:optional(row,"short_name"),categoryId:optional(row,"category_id"),categoryName:category?optional(category,"name"):undefined,baseUomId:text(row,"base_uom_id"),uomCode:text(uom??{},"code"),uomName:text(uom??{},"name"),specification:optional(row,"specification"),brand:optional(row,"brand"),manufacturer:optional(row,"manufacturer"),countryOfOrigin:optional(row,"country_of_origin"),trackedInventory:Boolean(row.tracked_inventory),status:text(row,"status") as InventoryItem["status"],note:optional(row,"note"),imageAssetId:image?optional(image,"id"):undefined,imageMimeType:image?optional(image,"mime_type"):undefined,totalOnHand:Number(row.total_on_hand??0),rowVersion:Number(row.row_version??1)};}
function mapWarehouse(row:Row):Warehouse{return{id:text(row,"id"),code:text(row,"code"),name:text(row,"name"),type:text(row,"type") as Warehouse["type"],address:optional(row,"address"),managerEmployeeId:optional(row,"manager_employee_id"),managerName:optional(nested(row,"employees")??{},"full_name"),projectId:optional(row,"project_id"),projectName:optional(nested(row,"projects")??{},"name"),worksiteId:optional(row,"worksite_id"),worksiteName:optional(nested(row,"worksites")??{},"name"),status:text(row,"status") as Warehouse["status"],note:optional(row,"note"),rowVersion:Number(row.row_version??1)};}
const itemSelect="*,item_categories(name),units_of_measure!inventory_items_base_uom_id_fkey(code,name),primary_image:file_assets!inventory_items_primary_image_file_id_fkey(id,mime_type)";
const warehouseSelect="*,employees(full_name),projects(name),worksites(name)";
const documentSelect="*,source:warehouses!inventory_documents_source_warehouse_id_fkey(name),target:warehouses!inventory_documents_target_warehouse_id_fkey(name),projects(name),worksites(name),creator:app_accounts!inventory_documents_created_by_fkey(display_name),poster:app_accounts!inventory_documents_posted_by_fkey(display_name),inventory_document_lines(quantity)";
const lineSelect="*,inventory_items(item_code,name),units_of_measure(code)";
function mapLine(row:Row):InventoryDocumentLine{const item=nested(row,"inventory_items"),uom=nested(row,"units_of_measure");return{id:text(row,"id"),itemId:text(row,"item_id"),itemCode:text(item??{},"item_code"),itemName:text(item??{},"name"),quantity:Number(row.quantity),adjustmentQuantity:row.adjustment_quantity==null?undefined:Number(row.adjustment_quantity),uomId:text(row,"uom_id"),uomCode:text(uom??{},"code"),unitPrice:row.unit_price==null?undefined:Number(row.unit_price),expectedQuantity:row.expected_quantity==null?undefined:Number(row.expected_quantity),shipmentLineId:optional(row,"shipment_line_id"),reference:optional(row,"reference"),purpose:optional(row,"purpose"),note:optional(row,"note"),rowVersion:Number(row.row_version??1)};}
function mapDocument(row:Row,lines:InventoryDocumentLine[]=[]):InventoryDocument{const summaryLines=Array.isArray(row.inventory_document_lines)?row.inventory_document_lines as Row[]:[];const quantities=lines.length?lines.map((line)=>line.quantity):summaryLines.map((line)=>Number(line.quantity));return{id:text(row,"id"),documentNumber:text(row,"document_number"),type:text(row,"type") as InventoryDocument["type"],status:text(row,"status") as InventoryDocument["status"],documentDate:text(row,"document_date"),postingDate:optional(row,"posting_date"),sourceWarehouseId:optional(row,"source_warehouse_id"),sourceWarehouseName:optional(nested(row,"source")??{},"name"),targetWarehouseId:optional(row,"target_warehouse_id"),targetWarehouseName:optional(nested(row,"target")??{},"name"),transactionTypeCode:text(row,"transaction_type_code"),supplierReference:optional(row,"supplier_reference"),shipmentId:optional(row,"shipment_id"),shipmentReceiptReference:optional(row,"shipment_receipt_reference"),projectId:optional(row,"project_id"),projectName:optional(nested(row,"projects")??{},"name"),worksiteId:optional(row,"worksite_id"),worksiteName:optional(nested(row,"worksites")??{},"name"),deliveredBy:optional(row,"delivered_by"),receivedBy:optional(row,"received_by"),recipient:optional(row,"recipient"),receivingDepartment:optional(row,"receiving_department"),note:optional(row,"note"),createdByName:optional(nested(row,"creator")??{},"display_name"),submittedAt:optional(row,"submitted_at"),postedAt:optional(row,"posted_at"),postedByName:optional(nested(row,"poster")??{},"display_name"),reversedAt:optional(row,"reversed_at"),reversalDocumentId:optional(row,"reversal_document_id"),reversesDocumentId:optional(row,"reverses_document_id"),rowVersion:Number(row.row_version??1),lineCount:quantities.length,totalQuantity:quantities.reduce((sum,quantity)=>sum+Math.abs(quantity),0),lines};}

export async function listUom():Promise<UnitOfMeasure[]>{const{data,error}=await db().from("units_of_measure").select("*").order("name");if(error)throw new AppError("SERVER_ERROR","Không thể đọc đơn vị tính.");return(data??[]).map((row)=>({id:String(row.id),code:row.code,name:row.name,symbol:row.symbol,active:row.active}));}
export async function listCategories():Promise<ItemCategory[]>{const{data,error}=await db().from("item_categories").select("*").order("sort_order").order("name");if(error)throw new AppError("SERVER_ERROR","Không thể đọc nhóm hàng.");return(data??[]).map((row)=>({id:String(row.id),code:row.code,name:row.name,parentId:row.parent_id??undefined,active:row.active,sortOrder:row.sort_order}));}
export async function listTransactionTypes(user:AuthenticatedUser,type?:string){requireWarehousePermission(user,"warehouse.view");let query=db().from("inventory_transaction_types").select("code,document_type,label,project_required,approval_required").eq("active",true).order("sort_order");if(type)query=query.eq("document_type",type);const{data,error}=await query;if(error)throw new AppError("SERVER_ERROR","Không thể đọc loại giao dịch kho.");return(data??[]).map((row)=>({code:row.code,documentType:row.document_type,label:row.label,projectRequired:row.project_required,approvalRequired:row.approval_required}));}
export async function listWarehouseReferences(user: AuthenticatedUser) {
  requireWarehousePermission(user, "warehouse.view");
  const client = db();
  const [projects, worksites, employees] = await Promise.all([
    readWarehouseRows(() => client.from("projects").select("id,code,name").neq("status", "closed").order("id"), "Không thể đọc dự án."),
    readWarehouseRows(() => client.from("worksites").select("id,project_id,name").eq("status", "active").order("id"), "Không thể đọc công trường."),
    can(user.permissions, "warehouse.master.manage") ? readWarehouseRows(() => client.from("employees").select("id,employee_code,full_name").eq("employment_status", "active").order("id"), "Không thể đọc người quản lý kho.") : Promise.resolve([])
  ]);
  return { projects: projects.map(row => ({ id: String(row.id), code: row.code, name: row.name })), worksites: worksites.map(row => ({ id: String(row.id), projectId: String(row.project_id), name: row.name })), employees: employees.map(row => ({ id: String(row.id), label: `${row.employee_code} · ${row.full_name}` })) };
}

export async function listWarehouses(user: AuthenticatedUser): Promise<Warehouse[]> {
  requireWarehousePermission(user, "warehouse.view");
  const client = db(), scope = await scopedWarehouseIds(client, user);
  if (scope && !scope.length) return [];
  const rows = await readWarehouseRows(() => { let query = client.from("warehouses").select(warehouseSelect).order("id"); if (scope) query = query.in("id", scope); return query; }, "Không thể đọc danh sách kho.");
  return rows.map(row => mapWarehouse(row as Row)).sort((a, b) => a.name.localeCompare(b.name, "vi"));
}

export async function listReceivingWarehouses(user: AuthenticatedUser): Promise<Warehouse[]> {
  requireWarehousePermission(user, "warehouse.receipt.create");
  const client = db(), scope = await scopedWarehouseIds(client, user, true);
  if (scope && !scope.length) return [];
  const rows = await readWarehouseRows(() => {
    let query = client.from("warehouses").select(warehouseSelect).eq("status", "active").order("id");
    if (scope) query = query.in("id", scope);
    return query;
  }, "Không thể đọc kho nhận hàng.");
  return rows.map(row => mapWarehouse(row as Row)).sort((a, b) => a.name.localeCompare(b.name, "vi"));
}

export async function listItems(user: AuthenticatedUser, filters: { search?: string; categoryId?: string; status?: string } = {}): Promise<InventoryItem[]> {
  requireWarehousePermission(user, "warehouse.item.view");
  const client = db(), scope = await scopedWarehouseIds(client, user);
  const [items, balances] = await Promise.all([
    readWarehouseRows(() => { let query = client.from("inventory_items").select(itemSelect).order("id"); if (filters.search) { const value = filters.search.replace(/[%,]/g, ""); query = query.or(`item_code.ilike.%${value}%,name.ilike.%${value}%`); } if (filters.categoryId) query = query.eq("category_id", filters.categoryId); if (filters.status) query = query.eq("status", filters.status); return query; }, "Không thể đọc hàng hóa."),
    scope && !scope.length ? Promise.resolve([]) : readWarehouseRows(() => { let query = client.from("inventory_balances").select("warehouse_id,item_id,on_hand").order("warehouse_id").order("item_id"); if (scope) query = query.in("warehouse_id", scope); return query; }, "Không thể đọc tồn hàng hóa.")
  ]);
  const totals = new Map<string, number>();
  for (const row of balances) totals.set(String(row.item_id), (totals.get(String(row.item_id)) ?? 0) + Number(row.on_hand));
  return items.map(row => mapItem({ ...row, total_on_hand: totals.get(String(row.id)) ?? 0 } as Row)).sort((a, b) => a.itemCode.localeCompare(b.itemCode, "vi"));
}

export async function getItem(user:AuthenticatedUser,id:string){const client=db();requireWarehousePermission(user,"warehouse.item.view");const{data,error}=await client.from("inventory_items").select(itemSelect).eq("id",id).maybeSingle();if(error||!data)throw new AppError("NOT_FOUND","Không tìm thấy hàng hóa.");const balances=(await listInventory(user,{search:data.item_code})).filter((row)=>row.itemId===id);return{...mapItem({...data,total_on_hand:balances.reduce((sum,row)=>sum+row.onHand,0)} as Row),balances};}
export async function createItem(user:AuthenticatedUser,input:z.infer<typeof itemSchema>){requireWarehousePermission(user,"warehouse.item.manage");const client=db(),identity=await actor(client,user);const{data,error}=await client.from("inventory_items").insert({item_code:input.itemCode,name:input.name,short_name:input.shortName??null,category_id:input.categoryId??null,base_uom_id:input.baseUomId,specification:input.specification??null,brand:input.brand??null,manufacturer:input.manufacturer??null,country_of_origin:input.countryOfOrigin??null,tracked_inventory:input.trackedInventory,status:input.status,note:input.note??null,created_by:identity.accountId??null}).select(itemSelect).single();if(error)throw new AppError(error.code==="23505"?"CONFLICT":"SERVER_ERROR",error.code==="23505"?"Mã hàng đã tồn tại.":"Không thể tạo hàng hóa.");await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.item.created",entityType:"inventory_item",entityId:String(data.id),after:{itemCode:input.itemCode}});return mapItem(data as Row);}
export async function updateItem(user:AuthenticatedUser,id:string,input:z.infer<typeof itemSchema>&{rowVersion:number}){requireWarehousePermission(user,"warehouse.item.manage");const client=db(),identity=await actor(client,user);const{data,error}=await client.from("inventory_items").update({item_code:input.itemCode,name:input.name,short_name:input.shortName??null,category_id:input.categoryId??null,base_uom_id:input.baseUomId,specification:input.specification??null,brand:input.brand??null,manufacturer:input.manufacturer??null,country_of_origin:input.countryOfOrigin??null,tracked_inventory:input.trackedInventory,status:input.status,note:input.note??null}).eq("id",id).eq("row_version",input.rowVersion).select(itemSelect).maybeSingle();if(error||!data)throw new AppError(error?.code==="23505"?"CONFLICT":"CONFLICT",error?.code==="23505"?"Mã hàng đã tồn tại.":"Hàng hóa vừa được người khác cập nhật.");await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.item.updated",entityType:"inventory_item",entityId:id,after:{itemCode:input.itemCode,status:input.status}});return mapItem(data as Row);}

const itemImageTypes = ["image/jpeg", "image/png", "image/webp"];
export async function replaceItemImage(user:AuthenticatedUser,itemId:string,file:File){requireWarehousePermission(user,"warehouse.item.manage");const client=db(),identity=await actor(client,user);const{data:current,error:currentError}=await client.from("inventory_items").select("id,primary_image_file_id").eq("id",itemId).maybeSingle();if(currentError||!current)throw new AppError("NOT_FOUND","Không tìm thấy hàng hóa.");const bytes=await validateUploadedFile(file,{allowedMimeTypes:itemImageTypes,maxBytes:5*1024*1024});const assetId=crypto.randomUUID(),safeName=safeUploadName(file.name,"product-image"),objectPath=`${itemId}/${assetId}-${safeName}`;const{error:uploadError}=await client.storage.from("warehouse-item-images").upload(objectPath,bytes,{contentType:file.type,upsert:false});if(uploadError)throw new AppError("SERVER_ERROR","Không thể tải ảnh hàng hóa.");const{error:assetError}=await client.from("file_assets").insert({id:assetId,bucket:"warehouse-item-images",object_path:objectPath,owner_entity_type:"inventory_item",owner_entity_id:itemId,mime_type:file.type,byte_size:file.size,visibility:"private",created_by:identity.accountId??null,metadata:{originalName:file.name}});if(assetError){await client.storage.from("warehouse-item-images").remove([objectPath]);throw new AppError("SERVER_ERROR","Không thể lưu thông tin ảnh hàng hóa.");}const{error:linkError}=await client.from("inventory_items").update({primary_image_file_id:assetId}).eq("id",itemId);if(linkError){await client.from("file_assets").delete().eq("id",assetId);await client.storage.from("warehouse-item-images").remove([objectPath]);throw new AppError("SERVER_ERROR","Không thể gắn ảnh vào hàng hóa.");}if(current.primary_image_file_id){const{data:oldAsset}=await client.from("file_assets").select("bucket,object_path").eq("id",current.primary_image_file_id).maybeSingle();if(oldAsset)await client.storage.from(oldAsset.bucket).remove([oldAsset.object_path]);await client.from("file_assets").delete().eq("id",current.primary_image_file_id);}await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.item.image_replaced",entityType:"inventory_item",entityId:itemId,metadata:{fileId:assetId,mimeType:file.type}});return getItem(user,itemId);}

export async function deleteItemImage(user:AuthenticatedUser,itemId:string){requireWarehousePermission(user,"warehouse.item.manage");const client=db(),identity=await actor(client,user);const{data:current,error}=await client.from("inventory_items").select("primary_image_file_id").eq("id",itemId).maybeSingle();if(error||!current)throw new AppError("NOT_FOUND","Không tìm thấy hàng hóa.");if(!current.primary_image_file_id)return getItem(user,itemId);const{data:asset}=await client.from("file_assets").select("bucket,object_path").eq("id",current.primary_image_file_id).maybeSingle();const{error:unlinkError}=await client.from("inventory_items").update({primary_image_file_id:null}).eq("id",itemId);if(unlinkError)throw new AppError("SERVER_ERROR","Không thể xóa ảnh hàng hóa.");if(asset)await client.storage.from(asset.bucket).remove([asset.object_path]);await client.from("file_assets").delete().eq("id",current.primary_image_file_id);await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.item.image_deleted",entityType:"inventory_item",entityId:itemId});return getItem(user,itemId);}
export async function createWarehouse(user:AuthenticatedUser,input:z.infer<typeof warehouseSchema>){ return saveWarehouseRecord(user,input); }

export async function getWarehouse(user:AuthenticatedUser,id:string){const client=db();requireWarehousePermission(user,"warehouse.view");await assertWarehouseAccess(client,user,id);const{data,error}=await client.from("warehouses").select(warehouseSelect).eq("id",id).maybeSingle();if(error||!data)throw new AppError("NOT_FOUND","Không tìm thấy kho.");return mapWarehouse(data as Row);}
export async function updateWarehouse(user:AuthenticatedUser,id:string,input:z.infer<typeof warehouseSchema>&{rowVersion:number}){ return saveWarehouseRecord(user,input,id,input.rowVersion); }

export async function createCategory(user:AuthenticatedUser,input:z.infer<typeof categorySchema>){requireWarehousePermission(user,"warehouse.master.manage");const{data,error}=await db().from("item_categories").insert({code:input.code,name:input.name,parent_id:input.parentId??null,active:input.active,sort_order:input.sortOrder}).select("*").single();if(error)throw new AppError(error.code==="23505"?"CONFLICT":"SERVER_ERROR","Không thể tạo nhóm hàng.");return{id:String(data.id),code:data.code,name:data.name,parentId:data.parent_id??undefined,active:data.active,sortOrder:data.sort_order};}
export async function createUom(user:AuthenticatedUser,input:z.infer<typeof uomSchema>){requireWarehousePermission(user,"warehouse.master.manage");const{data,error}=await db().from("units_of_measure").insert(input).select("*").single();if(error)throw new AppError(error.code==="23505"?"CONFLICT":"SERVER_ERROR","Không thể tạo đơn vị tính.");return{id:String(data.id),code:data.code,name:data.name,symbol:data.symbol,active:data.active};}
export async function updateCategory(user:AuthenticatedUser,id:string,input:z.infer<typeof categorySchema>){requireWarehousePermission(user,"warehouse.master.manage");const{data,error}=await db().from("item_categories").update({code:input.code,name:input.name,parent_id:input.parentId??null,active:input.active,sort_order:input.sortOrder}).eq("id",id).select("*").maybeSingle();if(error||!data)throw new AppError(error?.code==="23505"?"CONFLICT":"NOT_FOUND","Không thể cập nhật nhóm hàng.");return{id:String(data.id),code:data.code,name:data.name,parentId:data.parent_id??undefined,active:data.active,sortOrder:data.sort_order};}
export async function updateUom(user:AuthenticatedUser,id:string,input:z.infer<typeof uomSchema>){requireWarehousePermission(user,"warehouse.master.manage");const{data,error}=await db().from("units_of_measure").update(input).eq("id",id).select("*").maybeSingle();if(error||!data)throw new AppError(error?.code==="23505"?"CONFLICT":"NOT_FOUND","Không thể cập nhật đơn vị tính.");return{id:String(data.id),code:data.code,name:data.name,symbol:data.symbol,active:data.active};}
export async function getItemWarehouseSettings(user:AuthenticatedUser,itemId:string){await getItem(user,itemId);const client=db(),warehouses=await listWarehouses(user),{data}=await client.from("item_warehouse_settings").select("warehouse_id,minimum_stock,reorder_level").eq("item_id",itemId);const values=new Map((data??[]).map((row)=>[String(row.warehouse_id),row]));return warehouses.map((warehouse)=>{const value=values.get(warehouse.id);return{warehouseId:warehouse.id,warehouseCode:warehouse.code,warehouseName:warehouse.name,minimumStock:value?.minimum_stock==null?undefined:Number(value.minimum_stock),reorderLevel:value?.reorder_level==null?undefined:Number(value.reorder_level)};});}
export async function saveItemWarehouseSettings(user:AuthenticatedUser,itemId:string,input:Array<{warehouseId:string;minimumStock?:number;reorderLevel?:number}>){requireWarehousePermission(user,"warehouse.item.manage");await getItem(user,itemId);const client=db(),identity=await actor(client,user);for(const row of input){await assertWarehouseAccess(client,user,row.warehouseId,true);const{error}=await client.from("item_warehouse_settings").upsert({item_id:itemId,warehouse_id:row.warehouseId,minimum_stock:row.minimumStock??null,reorder_level:row.reorderLevel??null,updated_by:identity.accountId??null},{onConflict:"item_id,warehouse_id"});if(error)throw new AppError("SERVER_ERROR","Không thể lưu ngưỡng tồn kho.");}await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.item.thresholds_updated",entityType:"inventory_item",entityId:itemId,after:{warehouses:input.map((row)=>row.warehouseId)}});return getItemWarehouseSettings(user,itemId);}

function permissionFor(type:InventoryDocument["type"],action:"view"|"create"|"post"|"reverse"):Permission{const base=type==="reversal"?"receipt":type;return`warehouse.${base}.${action}` as Permission;}
export async function listDocuments(user:AuthenticatedUser,type?:InventoryDocument["type"],filters:z.infer<typeof warehouseListQuerySchema>={limit:50}){if(type&&type!=="reversal")requireWarehousePermission(user,permissionFor(type,"view"));else requireWarehousePermission(user,"warehouse.view");const client=db(),scope=await scopedWarehouseIds(client,user);if(scope&&!scope.length)return[];const allowedTypes=(['receipt','issue','transfer','adjustment'] as const).filter((value)=>can(user.permissions,permissionFor(value,"view")));if(!type&&!allowedTypes.length)return[];let query=client.from("inventory_documents").select(documentSelect).order("document_date",{ascending:false}).order("created_at",{ascending:false}).order("id").range(filters.offset??0,(filters.offset??0)+filters.limit-1);if(type)query=query.eq("type",type);else query=query.in("type",allowedTypes);if(filters.projectId)query=query.eq("project_id",filters.projectId);if(filters.worksiteId)query=query.eq("worksite_id",filters.worksiteId);if(filters.status)query=query.eq("status",filters.status);if(filters.from)query=query.gte("document_date",filters.from);if(filters.to)query=query.lte("document_date",filters.to);if(filters.search)query=query.ilike("document_number",`%${filters.search.replace(/[%,]/g,"")}%`);if(filters.warehouseId){await assertWarehouseAccess(client,user,filters.warehouseId);query=query.or(`source_warehouse_id.eq.${filters.warehouseId},target_warehouse_id.eq.${filters.warehouseId}`);}else if(scope)query=query.or(`source_warehouse_id.in.(${scope.join(",")}),target_warehouse_id.in.(${scope.join(",")})`);const{data,error}=await query;if(error)throw new AppError("SERVER_ERROR","Không thể đọc chứng từ kho.");return(data??[]).map((row)=>mapDocument(row as Row));}
export async function getDocument(user:AuthenticatedUser,id:string){const client=db();const{data,error}=await client.from("inventory_documents").select(documentSelect).eq("id",id).maybeSingle();if(error||!data)throw new AppError("NOT_FOUND","Không tìm thấy chứng từ.");const document=mapDocument(data as Row);requireWarehousePermission(user,document.type==="reversal"?"warehouse.view":permissionFor(document.type,"view"));for(const warehouseId of [document.sourceWarehouseId,document.targetWarehouseId])if(warehouseId)await assertWarehouseAccess(client,user,warehouseId);const{data:lines,error:lineError}=await client.from("inventory_document_lines").select(lineSelect).eq("document_id",id).order("line_number");if(lineError)throw new AppError("SERVER_ERROR","Không thể đọc dòng chứng từ.");return mapDocument(data as Row,(lines??[]).map((row)=>mapLine(row as Row)));}
export async function createDocument(user:AuthenticatedUser,input:z.infer<typeof inventoryDocumentSchema>){requireWarehousePermission(user,permissionFor(input.type,"create"));if(input.transactionTypeCode==="COUNT_VARIANCE")throw new AppError("VALIDATION_ERROR","Mã giao dịch này chỉ dùng cho kiểm kê.");const client=db(),identity=await actor(client,user);for(const warehouseId of [input.sourceWarehouseId,input.targetWarehouseId])if(warehouseId)await assertWarehouseAccess(client,user,warehouseId,true);const{data:number,error:numberError}=await client.rpc("next_inventory_document_number",{p_type:input.type,p_date:input.documentDate});if(numberError||!number)throw new AppError("SERVER_ERROR","Không thể cấp số chứng từ.");const{data:id,error}=await client.rpc("create_inventory_document",{p_number:number,p_client_request_id:input.clientRequestId??null,p_type:input.type,p_header:{document_date:input.documentDate,source_warehouse_id:input.sourceWarehouseId??null,target_warehouse_id:input.targetWarehouseId??null,transaction_type_code:input.transactionTypeCode,supplier_reference:input.supplierReference??null,shipment_id:input.shipmentId??null,shipment_receipt_reference:input.shipmentReceiptReference??null,project_id:input.projectId??null,worksite_id:input.worksiteId??null,delivered_by:input.deliveredBy??null,received_by:input.receivedBy??null,recipient:input.recipient??null,receiving_department:input.receivingDepartment??null,note:input.note??null},p_lines:input.lines.map((line,index)=>({line_number:index+1,item_id:line.itemId,quantity:line.quantity,adjustment_quantity:input.type==="adjustment"?line.adjustmentQuantity:null,uom_id:line.uomId,unit_price:line.unitPrice??null,expected_quantity:line.expectedQuantity??null,shipment_line_id:line.shipmentLineId??null,reference:line.reference??null,purpose:line.purpose??null,note:line.note??null})),p_actor_id:identity.accountId??null});if(error||!id)throw new AppError("SERVER_ERROR","Không thể tạo chứng từ và dòng hàng.");await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.document.created",entityType:"inventory_document",entityId:String(id),after:{type:input.type,documentNumber:number}});return getDocument(user,String(id));}
export async function updateDocument(user:AuthenticatedUser,id:string,input:z.infer<typeof inventoryDocumentPatchSchema>){const current=await getDocument(user,id);requireWarehousePermission(user,permissionFor(current.type,"create"));validatedInventoryDocument.parse({...input,type:current.type});if(input.transactionTypeCode==="COUNT_VARIANCE")throw new AppError("VALIDATION_ERROR","Mã giao dịch này chỉ dùng cho kiểm kê.");if(current.status!=="draft")throw new AppError("CONFLICT","Chứng từ đã ghi sổ không thể chỉnh sửa.");const client=db(),identity=await actor(client,user);for(const warehouseId of [input.sourceWarehouseId,input.targetWarehouseId])if(warehouseId)await assertWarehouseAccess(client,user,warehouseId,true);const{error}=await client.rpc("save_inventory_document",{p_document_id:id,p_row_version:input.rowVersion,p_header:{document_date:input.documentDate,source_warehouse_id:input.sourceWarehouseId??null,target_warehouse_id:input.targetWarehouseId??null,transaction_type_code:input.transactionTypeCode,supplier_reference:input.supplierReference??null,project_id:input.projectId??null,worksite_id:input.worksiteId??null,delivered_by:input.deliveredBy??null,received_by:input.receivedBy??null,recipient:input.recipient??null,receiving_department:input.receivingDepartment??null,note:input.note??null},p_lines:input.lines.map((line:z.infer<typeof documentLineSchema>)=>({item_id:line.itemId,quantity:line.quantity,adjustment_quantity:current.type==="adjustment"?line.adjustmentQuantity:null,uom_id:line.uomId,unit_price:line.unitPrice??null,expected_quantity:line.expectedQuantity??null,shipment_line_id:line.shipmentLineId??null,reference:line.reference??null,purpose:line.purpose??null,note:line.note??null}))});if(error)throw new AppError("CONFLICT",error.message.includes("DOCUMENT_VERSION_CONFLICT")?"Chứng từ vừa được người khác cập nhật.":"Không thể lưu chứng từ.");await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.document.edited",entityType:"inventory_document",entityId:id,before:{rowVersion:current.rowVersion},after:{rowVersion:current.rowVersion+1}});return getDocument(user,id);}
function postingError(error:{message?:string}){const message=error.message??"";if(message.includes("VERSION_CONFLICT"))return new AppError("CONFLICT","Dữ liệu vừa được cập nhật. Tải lại trước khi ghi sổ.");if(message.includes("COUNT_INCOMPLETE"))return new AppError("CONFLICT","Còn mặt hàng chưa nhập số thực kiểm.");if(message.includes("INSUFFICIENT_STOCK")){const[,available,requested]=message.split("|");return new AppError("CONFLICT",`Tồn kho không đủ. Khả dụng: ${available}. Yêu cầu xuất: ${requested}.`);}if(message.includes("WAREHOUSE_FROZEN"))return new AppError("CONFLICT","Kho đang được khóa để kiểm kê.");if(message.includes("COUNT_MOVEMENTS_DETECTED"))return new AppError("CONFLICT","Đã có giao dịch sau thời điểm chụp tồn. Cần tạo lại kiểm kê.");if(message.includes("OVER_RECEIPT_LIMIT"))return new AppError("CONFLICT","Tổng số lượng nhận vượt dung sai của lô hàng.");if(message.includes("INVALID_SHIPMENT_RECEIPT_LINE"))return new AppError("VALIDATION_ERROR","Dòng phiếu nhập không khớp lô hàng.");return new AppError("CONFLICT","Không thể ghi sổ chứng từ ở trạng thái hiện tại.");}
export async function postDocument(user:AuthenticatedUser,id:string,input:z.infer<typeof postDocumentSchema>){const current=await getDocument(user,id);requireWarehousePermission(user,permissionFor(current.type,"post"));if(input.allowNegativeOverride&&!can(user.permissions,"warehouse.adjustment.post"))throw new AppError("PERMISSION_DENIED","Bạn không có quyền cho phép âm kho.");const client=db(),identity=await actor(client,user);for(const warehouseId of [current.sourceWarehouseId,current.targetWarehouseId])if(warehouseId)await assertWarehouseAccess(client,user,warehouseId,true);const{error}=await client.rpc(input.rowVersion===undefined?"post_inventory_document":"post_inventory_document_versioned",{...(input.rowVersion===undefined?{}:{p_row_version:input.rowVersion}),p_document_id:id,p_actor_id:identity.accountId??null,p_posting_date:input.postingDate,p_idempotency_key:input.idempotencyKey,p_allow_negative:input.allowNegativeOverride,p_override_reason:input.overrideReason??null});if(error)throw postingError(error);await recordAuditLog({actorId:identity.accountId??user.id,action:`warehouse.${current.type}.posted`,entityType:"inventory_document",entityId:id,after:{postingDate:input.postingDate},reason:input.overrideReason});return getDocument(user,id);}
export async function reverseDocument(user:AuthenticatedUser,id:string,input:z.infer<typeof reverseDocumentSchema>){const current=await getDocument(user,id);requireWarehousePermission(user,permissionFor(current.type,"reverse"));const client=db(),identity=await actor(client,user);for(const warehouseId of [current.sourceWarehouseId,current.targetWarehouseId])if(warehouseId)await assertWarehouseAccess(client,user,warehouseId,true);const{data,error}=await client.rpc("reverse_inventory_document",{p_document_id:id,p_actor_id:identity.accountId??null,p_posting_date:input.postingDate,p_idempotency_key:input.idempotencyKey,p_reason:input.reason});if(error)throw postingError(error);await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.document.reversed",entityType:"inventory_document",entityId:id,reason:input.reason,after:{reversalDocumentId:data}});return getDocument(user,id);}

export async function listInventory(user: AuthenticatedUser, filters: { warehouseId?: string; warehouseIds?: string[]; categoryId?: string; search?: string; status?: string } = {}): Promise<InventoryBalance[]> {
  requireWarehousePermission(user, "warehouse.view");
  const client = db(), scope = await scopedWarehouseIds(client, user);
  if (scope && !scope.length || filters.warehouseIds && !filters.warehouseIds.length) return [];
  if (filters.warehouseIds && scope && filters.warehouseIds.some(id => !scope.includes(id))) throw new AppError("PERMISSION_DENIED");
  const selectedIds = filters.warehouseIds ?? scope;
  if (filters.warehouseId) await assertWarehouseAccess(client, user, filters.warehouseId);
  const [rows, settings] = await Promise.all([
    readWarehouseRows(() => { let query = client.from("inventory_balances").select("*,warehouses(code,name),inventory_items(item_code,name,category_id,item_categories(name),units_of_measure!inventory_items_base_uom_id_fkey(code))").order("warehouse_id").order("item_id"); if (filters.warehouseId) query = query.eq("warehouse_id", filters.warehouseId); else if (selectedIds) query = query.in("warehouse_id", selectedIds); return query; }, "Không thể đọc tồn kho."),
    readWarehouseRows(() => { let query = client.from("item_warehouse_settings").select("*,warehouses(code,name),inventory_items(item_code,name,category_id,item_categories(name),units_of_measure!inventory_items_base_uom_id_fkey(code))").order("warehouse_id").order("item_id"); if (filters.warehouseId) query = query.eq("warehouse_id", filters.warehouseId); else if (selectedIds) query = query.in("warehouse_id", selectedIds); return query; }, "Không thể đọc ngưỡng tồn kho.")
  ]);
  const minimums = new Map(settings.map(row => [`${row.warehouse_id}:${row.item_id}`, row.minimum_stock == null ? undefined : Number(row.minimum_stock)]));
  const balanceKeys = new Set(rows.map(row => `${row.warehouse_id}:${row.item_id}`));
  for (const row of settings) if (!balanceKeys.has(`${row.warehouse_id}:${row.item_id}`)) rows.push({ ...row, on_hand: 0 });
  const search = filters.search?.trim().toLocaleLowerCase("vi");
  return rows.flatMap(row => {
    const item = nested(row as Row, "inventory_items") ?? {}, warehouse = nested(row as Row, "warehouses") ?? {};
    if (filters.categoryId && item.category_id !== filters.categoryId || search && !`${item.item_code} ${item.name}`.toLocaleLowerCase("vi").includes(search)) return [];
    const onHand = Number(row.on_hand), minimum = minimums.get(`${row.warehouse_id}:${row.item_id}`);
    const status: InventoryBalance["status"] = onHand <= 0 ? "out_of_stock" : minimum !== undefined && onHand <= minimum ? "low_stock" : "in_stock";
    if (filters.status && filters.status !== status) return [];
    return [{ warehouseId: String(row.warehouse_id), warehouseCode: text(warehouse, "code"), warehouseName: text(warehouse, "name"), itemId: String(row.item_id), itemCode: text(item, "item_code"), itemName: text(item, "name"), categoryName: optional(nested(item, "item_categories") ?? {}, "name"), uomCode: text(nested(item, "units_of_measure") ?? {}, "code"), onHand, minimumStock: minimum, status, updatedAt: String(row.updated_at) }];
  });
}

