export async function getWarehouseDashboard(user: AuthenticatedUser): Promise<WarehouseDashboard> {
  requireWarehousePermission(user, "warehouse.view");
  const client = db(), scope = await scopedWarehouseIds(client, user);
  const allowed = (["receipt", "issue", "transfer", "adjustment"] as const).filter(type => can(user.permissions, permissionFor(type, "view")));
  const countPending = async (type?: string) => {
    if (scope && !scope.length || !allowed.length || type && !allowed.includes(type as typeof allowed[number])) return 0;
    let query = client.from("inventory_documents").select("id", { count: "exact", head: true }).in("status", ["draft", "submitted"]).in("type", type ? [type] : allowed);
    if (scope) query = query.or(`source_warehouse_id.in.(${scope.join(",")}),target_warehouse_id.in.(${scope.join(",")})`);
    const { count, error } = await query; if (error) throw new AppError("SERVER_ERROR", "Không thể đọc số chứng từ chờ ghi sổ."); return count ?? 0;
  };
  const [warehouses, inventory, recentDocuments, drafts, submitted, pendingDocuments, pendingReceipts, pendingIssues, pendingTransfers, pendingAdjustments, counts] = await Promise.all([
    listWarehouses(user), listInventory(user), listDocuments(user, undefined, { limit: 8 }), listDocuments(user, undefined, { status: "draft", limit: 8 }), listDocuments(user, undefined, { status: "submitted", limit: 8 }), countPending(), countPending("receipt"), countPending("issue"), countPending("transfer"), countPending("adjustment"), can(user.permissions, "warehouse.stock_count.view") ? listStockCounts(user) : Promise.resolve([])
  ]);
  return { itemCount: new Set(inventory.map(row => row.itemId)).size, warehouseCount: warehouses.length, totalOnHand: inventory.reduce((sum, row) => sum + row.onHand, 0), outOfStock: inventory.filter(row => row.status === "out_of_stock").length, lowStock: inventory.filter(row => row.status === "low_stock").length, pendingDocuments, pendingReceipts, pendingIssues, pendingTransfers, pendingAdjustments, pendingStockCounts: counts.filter(row => ["counting", "reviewed"].includes(row.status)), pendingDocumentItems: [...drafts, ...submitted].sort((a, b) => a.documentDate.localeCompare(b.documentDate)).slice(0, 8), recentDocuments, lowStockItems: inventory.filter(row => row.status !== "in_stock").sort((a, b) => a.status === b.status ? a.itemCode.localeCompare(b.itemCode) : a.status === "out_of_stock" ? -1 : 1).slice(0, 8) };
}

export async function getReceivedQuantityByShipmentLine(user:AuthenticatedUser,shipmentLineId:string){requireWarehousePermission(user,"warehouse.receipt.view");const{data,error}=await db().from("inventory_document_lines").select("quantity,inventory_documents!inner(type,status)").eq("shipment_line_id",shipmentLineId).eq("inventory_documents.type","receipt").eq("inventory_documents.status","posted");if(error)throw new AppError("SERVER_ERROR","Không thể tổng hợp số lượng đã nhận.");return(data??[]).reduce((sum,row)=>sum+Number(row.quantity),0);}
