export function createWarehouseReceiptFromShipment(user:AuthenticatedUser,input:CreateWarehouseReceiptFromShipment){return createDocument(user,{type:"receipt",clientRequestId:input.clientRequestId,documentDate:input.receivedDate,targetWarehouseId:input.warehouseId,transactionTypeCode:"IMPORT",shipmentId:input.shipmentId,shipmentReceiptReference:input.reference,lines:input.lines.map((line)=>({itemId:line.itemId,quantity:line.quantity,uomId:line.uomId,shipmentLineId:line.shipmentLineId,reference:line.shipmentLineId,note:line.note}))});}

const warehouseAttachmentTypes:Record<string,"image"|"pdf"|"spreadsheet"|"document">={"image/jpeg":"image","image/png":"image","image/webp":"image","application/pdf":"pdf","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"spreadsheet","application/vnd.openxmlformats-officedocument.wordprocessingml.document":"document"};
export async function listInventoryDocumentAttachments(user:AuthenticatedUser,documentId:string){await getDocument(user,documentId);const{data,error}=await db().from("inventory_document_attachments").select("id,file_id,attachment_type,caption,uploaded_at,sort_order,file_assets(mime_type,byte_size,metadata)").eq("document_id",documentId).order("sort_order").order("uploaded_at");if(error)throw new AppError("SERVER_ERROR","Không thể đọc tệp chứng từ.");return(data??[]).map((row)=>{const file=nested(row as Row,"file_assets")??{},metadata=file.metadata&&typeof file.metadata==="object"?file.metadata as Row:{};return{id:String(row.id),fileId:String(row.file_id),attachmentType:row.attachment_type,fileName:text(metadata,"originalName","Tệp đính kèm"),mimeType:text(file,"mime_type"),sizeBytes:Number(file.byte_size??0),caption:row.caption??undefined,uploadedAt:row.uploaded_at};});}
export async function uploadInventoryDocumentAttachment(user:AuthenticatedUser,documentId:string,file:File,caption?:string){const document=await getDocument(user,documentId);requireWarehousePermission(user,document.type==="reversal"?"warehouse.receipt.create":permissionFor(document.type,"create"));const attachmentType=warehouseAttachmentTypes[file.type];if(!attachmentType)throw new AppError("VALIDATION_ERROR","Tệp không đúng định dạng.");const bytes=await validateUploadedFile(file,{allowedMimeTypes:Object.keys(warehouseAttachmentTypes),maxBytes:10*1024*1024});const client=db(),identity=await actor(client,user),assetId=crypto.randomUUID(),safeName=safeUploadName(file.name,"attachment"),objectPath=`${documentId}/${assetId}-${safeName}`;const{error:uploadError}=await client.storage.from("warehouse-documents").upload(objectPath,bytes,{contentType:file.type,upsert:false});if(uploadError)throw new AppError("SERVER_ERROR","Không thể tải tệp chứng từ.");const{error:assetError}=await client.from("file_assets").insert({id:assetId,bucket:"warehouse-documents",object_path:objectPath,owner_entity_type:"inventory_document",owner_entity_id:documentId,mime_type:file.type,byte_size:file.size,visibility:"private",created_by:identity.accountId??null,metadata:{originalName:file.name}});if(assetError){await client.storage.from("warehouse-documents").remove([objectPath]);throw new AppError("SERVER_ERROR","Không thể lưu thông tin tệp chứng từ.");}const{error:linkError}=await client.from("inventory_document_attachments").insert({document_id:documentId,file_id:assetId,attachment_type:attachmentType,caption:caption?.trim()||null,uploaded_by:identity.accountId??null});if(linkError){await client.from("file_assets").delete().eq("id",assetId);await client.storage.from("warehouse-documents").remove([objectPath]);throw new AppError("SERVER_ERROR","Không thể gắn tệp vào chứng từ.");}await recordAuditLog({actorId:identity.accountId??user.id,action:"warehouse.document.attachment_added",entityType:"inventory_document",entityId:documentId,metadata:{fileId:assetId,mimeType:file.type}});return(await listInventoryDocumentAttachments(user,documentId)).find((item)=>item.fileId===assetId);}
export async function auditInventoryBalanceConsistency(user:AuthenticatedUser){requireWarehousePermission(user,"warehouse.ledger.view");requireWarehousePermission(user,"warehouse.adjustment.post");const client=db(),scope=await scopedWarehouseIds(client,user);if(scope&&!scope.length)return[];const{data,error}=await client.rpc("audit_inventory_balance",{p_warehouse_ids:scope??null});if(error)throw new AppError("SERVER_ERROR","Không thể đối chiếu sổ kho.");return(data??[]).map((row:Row)=>({warehouseId:String(row.warehouse_id),itemId:String(row.item_id),ledgerQuantity:Number(row.ledger_quantity),balanceQuantity:Number(row.balance_quantity),difference:Number(row.difference)}));}
export async function cancelWarehouseRecord(user: AuthenticatedUser, id: string, kind: "stock_count" | "document", input: { rowVersion: number; reason: string }) {
  const client = db(), identity = await actor(client, user);
  const current = kind === "stock_count" ? await getStockCount(user, id) : await getDocument(user, id);
  requireWarehousePermission(user, kind === "stock_count" ? "warehouse.stock_count.create" : permissionFor((current as InventoryDocument).type, "create"));
  const warehouseIds = kind === "stock_count" ? [(current as StockCount).warehouseId] : [(current as InventoryDocument).sourceWarehouseId, (current as InventoryDocument).targetWarehouseId];
  for (const warehouseId of warehouseIds) if (warehouseId) await assertWarehouseAccess(client, user, warehouseId, true);
  const { error } = await client.rpc("cancel_warehouse_record", { p_id: id, p_kind: kind, p_row_version: input.rowVersion, p_actor_id: identity.accountId, p_reason: input.reason });
  if (error) throw new AppError("CONFLICT", error.message.includes("VERSION_CONFLICT") ? "Dữ liệu vừa được người khác cập nhật. Tải lại trước khi hủy." : "Chỉ có thể hủy dữ liệu chưa ghi sổ.");
  await recordAuditLog({ actorId: identity.accountId ?? user.id, action: `warehouse.${kind}.cancelled`, entityType: kind === "stock_count" ? "stock_count" : "inventory_document", entityId: id, reason: input.reason });
  return kind === "stock_count" ? getStockCount(user, id) : getDocument(user, id);
}

async function saveWarehouseRecord(user: AuthenticatedUser, input: z.infer<typeof warehouseSchema>, id?: string, rowVersion?: number) {
  requireWarehousePermission(user, "warehouse.master.manage");
  const client = db(), identity = await actor(client, user);
  if (id) await assertWarehouseAccess(client, user, id, true);
  const { data, error } = await client.rpc("save_warehouse_record", { p_id: id ?? null, p_row_version: rowVersion ?? null, p_actor_id: identity.accountId, p_values: input });
  if (error || !data) {
    const messages: Record<string, string> = { WAREHOUSE_HAS_STOCK: "Kho còn tồn hàng. Chuyển hết hàng trước khi ngừng sử dụng.", WAREHOUSE_FROZEN: "Hoàn tất hoặc hủy kiểm kê trước khi ngừng kho.", INVALID_PROJECT_WORKSITE: "Công trường không thuộc dự án đã chọn.", WAREHOUSE_VERSION_CONFLICT: "Kho vừa được người khác cập nhật." };
    throw new AppError("CONFLICT", error?.code === "23505" ? "Mã kho đã tồn tại." : Object.entries(messages).find(([key]) => error?.message.includes(key))?.[1] ?? "Không thể lưu kho.");
  }
  await recordAuditLog({ actorId: identity.accountId ?? user.id, action: id ? "warehouse.updated" : "warehouse.created", entityType: "warehouse", entityId: String(data), after: { code: input.code, status: input.status } });
  return getWarehouse(user, String(data));
}
